namespace FlowPro.Application.Common;

/// <summary>
/// A transaction scoped to a tenant that does not exist in the caller's identity yet.
/// </summary>
/// <remarks>
/// Every tenant-owned table enforces row level security against
/// <c>infrastructure.current_tenant_id()</c>. Workspace provisioning creates the tenant it is
/// about to write into, so the tenant identifier is generated by the caller and supplied here to
/// establish the row level security scope for the duration of the transaction. Regular workflows
/// must keep using <see cref="IUnitOfWork" />, which derives the scope from the authenticated
/// identity and cannot be pointed at an arbitrary tenant.
/// </remarks>
public interface IProvisioningUnitOfWork
{
    Task<TResult> ExecuteInTenantScopeAsync<TResult>(
        Guid tenantId,
        Func<CancellationToken, Task<TResult>> operation,
        CancellationToken cancellationToken);
}
